INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12501, 454889, 'tt6053440', NULL, 'Princess Cyd', 'Princess Cyd', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/7ZhF8acObc0R5tIETl7doRO1Bac.jpg', 'https://image.tmdb.org/t/p/original/9morAQCYVynv69UQDV4iVkUgOHN.jpg', 'High school athlete Cyd Loughlin lives alone with her depressive father in South Carolina, perpetually longing to get away from it all. When her aunt, famous novelist Miranda Ruth, agrees to host her for a few weeks during the summer, Cyd jumps at the opportunity. While there, she falls for a girl in the neighborhood, even as she and her aunt gently challenge each other in the realms of sex and spirit.', NULL, NULL, 1.5903, 6.57, 0, 1.11, '2026-08-28 09:15:01', '2026-08-28 09:15:01');
