INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12510, NULL, NULL, 267447, 'Return or No Return', 'Return or No Return', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co73sj.jpg', NULL, '"Return or No Return" is a first-person horror survival game set in a mansion that traps travelers passing through the infamous shortcut- The Tenebris Tunnel. After a mysterious smoke sweeps through the car, your friends have disappeared, and you''re trapped! You must save them to escape death.', 'https://www.igdb.com/games/return-or-no-return', NULL, NULL, NULL, 0, 10.43, '2026-08-28 09:15:02', '2026-08-28 09:15:02');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12511, NULL, NULL, 8652, 'Axiom Verge', 'Axiom Verge', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1kml.jpg', NULL, 'After a lab accident, a scientist awakens in a mysterious, alien world. Is this a distant planet? The far future? Or a complex virtual-reality computer simulation?

Plumb the recesses of a large, labyrinthine world in order to learn its secrets and uncover your role within it. Discover tons of weapons, items, and abilities, each with their own unique behaviors and usage. You’ll need your wits to find them all.
Combat bizarre biomechanoid constructs, the deadly fallout of an ancient war, and the demons of your own psyche.

And finally, break the game itself by using glitches to corrupt foes and solve puzzles in the environment. Life. Afterlife. Real. Virtual. Dream. Nightmare. It''s a thin line.

It''s Axiom Verge.', 'https://www.igdb.com/games/axiom-verge', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Wii U", "PlayStation Vita", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 8.52, '2026-08-28 09:15:02', '2026-08-28 09:15:02');
