INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12534, 10652, 'tt0093137', NULL, 'Hamburger Hill', 'Hamburger Hill', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/a84FDoIm64qcyKq6BEMB9Ycldpt.jpg', 'https://image.tmdb.org/t/p/original/pRpg9OAe4hrThTPxPSPzc185f0D.jpg', 'The men of Bravo Company are facing a battle that''s all uphill… up Hamburger Hill. Fourteen war-weary soldiers are battling for a mud-covered mound of earth so named because it chews up soldiers like chopped meat. They are fighting for their country, their fellow soldiers and their lives. War is hell, but this is worse. Hamburger Hill tells it the way it was, the way it really was. It''s a raw, gritty and totally unrelenting dramatic depiction of one of the fiercest battles of America''s bloodiest war. This happened. Hamburger Hill - war at its worst, men at their best.', NULL, NULL, 4.8518, 6.6, 0, 1.03, '2026-08-28 09:15:02', '2026-08-28 09:15:02');
