INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12594, 450608, 'tt5654600', NULL, 'Saturday Church', 'Saturday Church', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/kKRNAOOyRMIcO8ZMLg74YeaeyTB.jpg', 'https://image.tmdb.org/t/p/original/lpxMzlCGGtFbfxlbcoWH43UhIu8.jpg', 'Ulysses is a shy and effeminate boy who finds himself coping with new responsibilities as man of the house after the death of his father. Living alongside his mother, younger brother, and conservative aunt, Ulysses is also struggling with questions about his gender identity. He finds an escape by creating a world of fantasy filled with dance and music. Ulysses'' journey takes a turn for the better when he finds a vibrant transgender community.', NULL, NULL, 1.2764, 6.2, 0, 1.01, '2026-08-28 09:15:02', '2026-08-28 09:15:02');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12595, 10174, 'tt0102370', NULL, 'Madonna: Truth or Dare', 'Madonna: Truth or Dare', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/kJHCqwDgS9MEhdChIkGn7QAUoyL.jpg', 'https://image.tmdb.org/t/p/original/tIj48gA5trtzHv5onQd5HpC5pmS.jpg', 'From the rains of Japan, through threats of arrest for ''public indecency'' in Canada, and a birthday tribute to her father in Detroit, this documentary follows Madonna on her 1990 ''Blond Ambition'' concert tour. Filmed in black and white, with the concert pieces in glittering MTV color, it is an intimate look at the work of the icon, from a prayer circle before each performance to bed games with the dance troupe afterwards.', NULL, NULL, 2.8825, 6.198, 0, 2.01, '2026-08-28 09:15:02', '2026-08-28 09:15:02');
