INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12597, 97049, 'tt0103099', NULL, 'Tongues Untied', 'Tongues Untied', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/wbrcRd695aB8D6pkWh0hSurKRbO.jpg', 'https://image.tmdb.org/t/p/original/8Tvq2tkvr8LslXJpwjWPEap4BNa.jpg', 'Marlon Riggs, with assistance from other gay Black men, especially poet Essex Hemphill, celebrates Black men loving Black men as a revolutionary act. The film intercuts footage of Hemphill reciting his poetry, Riggs telling the story of his growing up, scenes of men in social intercourse and dance, and various comic riffs, including a visit to the "Institute of Snap!thology," where men take lessons in how to snap their fingers: the sling snap, the point snap, the diva snap.', NULL, NULL, 2.359, 6.629, 0, 1.01, '2026-08-28 09:15:02', '2026-08-28 09:15:02');
