INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12621, 23945, 'tt0115836', NULL, 'Carpool', 'Carpool', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/rYoZR4EtrfziT5WXhZzcNbH5GuE.jpg', 'https://image.tmdb.org/t/p/original/8LtMkl1d8gu4JJrtiOUSDSnGdG7.jpg', 'A man with an important business meeting finds himself having to take care of the carpool for the neighborhood school children when his wife gets sick. Stopping to get donuts for the kids, things go even more awry when he finds himself a victim of a robbery. However, the situation only gets worse as a desperate man who had been contemplating a bank robbery robs the robbers and takes the man and the kids hostage in their van as his truck is blocked by an armored car. The thing then proceeds into a comedic chase movie. The father finds his kids don''t really respect him and they react better to the robber. The end result is everyone gets a lifestyle change, including the original store owner.', NULL, NULL, 2.1228, 5.22, 0, 11.01, '2026-08-28 09:15:02', '2026-08-28 09:15:02');
