INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12626, 82685, 'tt1562849', NULL, 'Division III: Football''s Finest', 'Division III: Football''s Finest', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/1QEZCXEiXIXkynDmHuBa3wSS8QQ.jpg', 'https://image.tmdb.org/t/p/original/g8v3ne6angu0S9vk5y1ldRo05YN.jpg', 'This ensemble comedy follows the Pullham University Bluecocks, a small liberal arts college with a Division III football program (the lowest division in the NCAA). When the head coach unexpectedly dies, the future of the flailing football program is in jeopardy, as they have not had a winning season in decades. In a desperate attempt to create some media attention for the athletic program and the university, President Georgia Anne Whistler hires known lunatic and felon, Coach Rick Vice, for what could be the football programs final season.', NULL, NULL, 1.4433, 3.9, 0, 10.01, '2026-08-28 09:15:02', '2026-08-28 09:15:02');
