UPDATE "recommendations" SET "tmdb_id"=82507, "imdb_id"='tt1922777', "igdb_id"=NULL, "title"='Sinister', "original_title"='Sinister', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nzx10sca3arCeYBAomHan4Q6wa1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jovIEk4cAxWmA2dBcPrfhn3jzYN.jpg', "overview"='True-crime writer Ellison Oswalt is in a slump; he hasn''t had a best seller in more than 10 years and is becoming increasingly desperate for a hit. So, when he discovers the existence of a snuff film showing the deaths of a family, he vows to solve the mystery. He moves his own family into the victims'' home and gets to work. However, when old film footage and other clues hint at the presence of a supernatural force, Ellison learns that living in the house may be fatal.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.8983, "vote_average"=6.876, "is_ambiguous"=0, "evidence_score"=4.31239999999999952e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-28 09:15:02' WHERE "id"=791;
