UPDATE "recommendations" SET "tmdb_id"=10074, "imdb_id"='tt0787475', "igdb_id"=NULL, "title"='Hot Rod', "original_title"='Hot Rod', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/jRkt03dXCVKnbvcQm3ygU1cjg9Y.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/R0p2aJVD7NTrCJFbDlTPKoVCCz.jpg', "overview"='For Rod Kimble, performing stunts is a way of life, even though he is rather accident-prone. Poor Rod cannot even get any respect from his stepfather, Frank, who beats him up in weekly sparring matches. When Frank falls ill, Rod devises his most outrageous stunt yet to raise money for Frank''s operation -- and then Rod will kick Frank''s butt.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.28, "vote_average"=6.403, "is_ambiguous"=0, "evidence_score"=15.823, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-28 09:15:02' WHERE "id"=1305;
