UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=538, "title"='BioShock Infinite', "original_title"='BioShock Infinite', "media_type"='game', "release_year"=2013, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co2n12.jpg', "backdrop_url"=NULL, "overview"='BioShock Infinite is the third game in the BioShock series. It is not a direct sequel/prequel to any of the previous BioShock games but takes place in an entirely different setting, although it shares similar features, gameplay and concepts with the previous games. BioShock Infinite features a range of environments that force the player to adapt, with different weapons and strategies for each situation. Interior spaces feature close combat with enemies, but unlike previous games set in Rapture, the setting of Infinite contains open spaces with emphasis on sniping and ranged combat against as many as fifteen enemies at once.', "external_url"='https://www.igdb.com/games/bioshock-infinite', "platforms"='["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=2.13626666666666693e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-28 09:15:02' WHERE "id"=1944;
