UPDATE "recommendations" SET "tmdb_id"=82633, "imdb_id"='tt1212450', "igdb_id"=NULL, "title"='Lawless', "original_title"='Lawless', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/Ahtzwts22ayviD3LEVslfL4nRWB.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6zTqEmFWlmmPPY907qwvv9WQBUm.jpg', "overview"='In 1931, the Bondurant brothers of Franklin County, Virginia, run a multipurpose backwoods establishment that hides their true business — bootlegging. Middle brother Forrest is the brain of the operation; older Howard is the brawn, and younger Jack, the lookout. Though the local police have taken bribes and left the brothers alone, a violent war erupts when a sadistic lawman from Chicago arrives and tries to shut down the Bondurants operation.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.1568, "vote_average"=7.07, "is_ambiguous"=0, "evidence_score"=1.7774166666666666e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-28 09:15:02' WHERE "id"=2569;
