UPDATE "recommendations" SET "tmdb_id"=9408, "imdb_id"='tt0423294', "igdb_id"=NULL, "title"='Surf''s Up', "original_title"='Surf''s Up', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/tTDsCVlDA8QR4Dc6t6nERfwl5z.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/Y50RfoNVKIj9dSJavE8uBdN377.jpg', "overview"='With a documentary crew in tow, Cody Maverick—a young surfer from Antarctica—travels to the pacific for his first professional competition. Determined to earn respect and live up to his idol, Big Z, Cody pushes himself to the limit. But all that changes when an encounter with a laid-back local forces him to rethink his values.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.0479, "vote_average"=6.515, "is_ambiguous"=0, "evidence_score"=1.40207692307692308e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-28 09:15:02' WHERE "id"=3450;
UPDATE "recommendations" SET "tmdb_id"=9266, "imdb_id"='tt0300532', "igdb_id"=NULL, "title"='Blue Crush', "original_title"='Blue Crush', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/iZSw0JVG0cIFuZoTHuQU3nmGT4k.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xsVMKdSndUKid3Xm3Tudf5bcOlv.jpg', "overview"='Nothing gets between Anne Marie and her board. Living in a beach shack with three roommates, she is up before dawn every morning to conquer the waves and count the days until the Pipe Masters competition. Having transplanted herself to Hawaii with no one''s blessing but her own, Anne Marie finds all she needs in the adrenaline-charged surf scene - until pro quarterback Matt Tollman comes along...', "external_url"=NULL, "platforms"=NULL, "popularity"=3.495, "vote_average"=6.0, "is_ambiguous"=0, "evidence_score"=3.33612903225806434e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-28 09:15:02' WHERE "id"=3451;
UPDATE "recommendations" SET "tmdb_id"=9870, "imdb_id"='tt0800039', "igdb_id"=NULL, "title"='Forgetting Sarah Marshall', "original_title"='Forgetting Sarah Marshall', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/d4elOzyhNWVlxpG7BwigrumkFTe.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/s39aQY3dK1s6ARrUKP5yeq824nR.jpg', "overview"='When actress Sarah Marshall dumps aspiring musician Peter Bretter for rock star Aldous Snow, Peter''s world comes crashing down. His best friend Brian suggests that Peter should get away from everything and to fly off to Hawaii to escape all his problems. After arriving in Hawaii and meeting the beautiful receptionist Rachel Jansen, Peter is shocked to see not only Aldous in Hawaii, but also Sarah.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.4778, "vote_average"=6.506, "is_ambiguous"=0, "evidence_score"=2.03517647058823563e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-28 09:15:02' WHERE "id"=3462;
UPDATE "recommendations" SET "tmdb_id"=1824, "imdb_id"='tt0343660', "igdb_id"=NULL, "title"='50 First Dates', "original_title"='50 First Dates', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/lzUI2Cg7OMfcUNv3f7MywYNBjs6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/v8lPo8UWKyP2tIXD8N64HfNP4Pw.jpg', "overview"='Henry is a player skilled at seducing women. But when this veterinarian meets Lucy, a girl with a quirky problem when it comes to total recall, he realizes it''s possible to fall in love all over again…and again, and again. That''s because the delightful Lucy has no short-term memory, so Henry must woo her day after day until he finally sweeps her off her feet.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.5692, "vote_average"=6.9, "is_ambiguous"=0, "evidence_score"=1.64864285714285721e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-28 09:15:02' WHERE "id"=3467;
UPDATE "recommendations" SET "tmdb_id"=194766, "imdb_id"='tt14016500', "igdb_id"=NULL, "title"='The Summer I Turned Pretty', "original_title"='The Summer I Turned Pretty', "media_type"='tv', "release_year"=2022, "poster_url"='https://image.tmdb.org/t/p/w500/xBIz53wYWsKfFpN0TaizVAjKJ0z.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jCQV3rHNbgHKo3N4G6CARbVEjPV.jpg', "overview"='Every summer, Belly and her family head to the Fishers’ beach house in Cousins. Every summer is the same ... until Belly turns sixteen. Relationships will be tested, painful truths will be revealed, and Belly will be forever changed. It’s a summer of first love, first heartbreak and growing up — it''s the summer she turns pretty.', "external_url"=NULL, "platforms"=NULL, "popularity"=47.6386, "vote_average"=8.074, "is_ambiguous"=0, "evidence_score"=1.51215384615384618e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-28 09:15:01' WHERE "id"=3492;
UPDATE "recommendations" SET "tmdb_id"=10591, "imdb_id"='tt0265208', "igdb_id"=NULL, "title"='The Girl Next Door', "original_title"='The Girl Next Door', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/5mVyFHSY2rSsNgD4NfEwV82HigU.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qvcOovScPoRalRxDy50rYSYFree.jpg', "overview"='Exceptionally ambitious high schooler Matthew has aspirations for a career in politics when he falls in love with his gorgeous 19-year-old neighbor, Danielle. But Matthew''s bright future is jeopardized when he finds Danielle was once a porn star. As Danielle''s past catches up with her, Matthew''s love for her forces him to re-evaluate his goals.', "external_url"=NULL, "platforms"=NULL, "popularity"=17.6799, "vote_average"=6.752, "is_ambiguous"=0, "evidence_score"=8.78166666666666628e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-28 09:15:02' WHERE "id"=3502;
UPDATE "recommendations" SET "tmdb_id"=8195, "imdb_id"='tt0122690', "igdb_id"=NULL, "title"='Ronin', "original_title"='Ronin', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/AirrhRJjHwytOV0pdLu7YZ4DEyr.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/frqahc6v8wt0p2Zo3XKBu2dg73z.jpg', "overview"='A briefcase with undisclosed contents – sought by Irish terrorists and the Russian mob – makes its way into criminals'' hands. An Irish liaison assembles a squad of mercenaries, or ''ronin'', and gives them the thorny task of recovering the case.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.9009, "vote_average"=7.0, "is_ambiguous"=0, "evidence_score"=8.668, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-28 09:15:02' WHERE "id"=3519;
