UPDATE "recommendations" SET "tmdb_id"=13916, "imdb_id"='tt0877057', "igdb_id"=NULL, "title"='Death Note', "original_title"='DEATH NOTE', "media_type"='tv', "release_year"=2006, "poster_url"='https://image.tmdb.org/t/p/w500/tCZFfYTIwrR7n94J6G14Y4hAFU6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/z8IPicmEKXUO4I2UDdMEqw7RqOE.jpg', "overview"='Light Yagami is an ace student with great prospects—and he’s bored out of his mind. But all that changes when he finds the Death Note, a notebook dropped by a rogue Shinigami death god. Any human whose name is written in the notebook dies, and Light has vowed to use the power of the Death Note to rid the world of evil. But will Light succeed in his noble goal, or will the Death Note turn him into the very thing he fights against?', "external_url"=NULL, "platforms"=NULL, "popularity"=35.3527, "vote_average"=8.622, "is_ambiguous"=0, "evidence_score"=7.35833333333333339e+00, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-28 09:15:02' WHERE "id"=3865;
