UPDATE "recommendations" SET "tmdb_id"=19947, "imdb_id"='tt0088678', "igdb_id"=NULL, "title"='The Adventures of Mark Twain', "original_title"='The Adventures of Mark Twain', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/wUYyl69qvIZOTuRJnwK07BbYSyy.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/oLVeYWiTEtd530oXVPABp334vJZ.jpg', "overview"='Based on elements from the stories of Mark Twain, this feature-length Claymation fantasy follows the adventures of Tom Sawyer, Becky Thatcher and Huck Finn as they stowaway aboard the interplanetary balloon of Mark Twain. Twain, disgusted with the human race, is intent upon finding Halley''s Comet and crashing into it, achieving his "destiny." It''s up to Tom, Becky, and Huck to convince him that his judgment is wrong and that he still has much to offer humanity that might make a difference. Their efforts aren''t just charitable; if they fail, they will share Twain''s fate. Along the way, they use a magical time portal to get a detailed overview of the Twain philosophy, observing the "historical" events that inspired his works.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8178, "vote_average"=6.741, "is_ambiguous"=0, "evidence_score"=8.5875, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-28 09:15:02' WHERE "id"=4071;
