UPDATE "recommendations" SET "tmdb_id"=291272, "imdb_id"='tt3520418', "igdb_id"=NULL, "title"='We Are Still Here', "original_title"='We Are Still Here', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/f8Btwn93gNycI1tFo29Gy1zB5kv.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bUV1ObIIeCzIUKE4iucetXvFIh7.jpg', "overview"='After the death of their college age son, Anne and Paul Sacchetti relocate to the snowswept New England hamlet of Aylesbury, a sleepy village where all is most certainly not as it seems. When strange sounds and eerie feelings convince Anne that her son''s spirit is still with them, they invite an eccentric, New Age couple to help them get to the bottom of the mystery.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.5914, "vote_average"=5.614, "is_ambiguous"=0, "evidence_score"=1.08233333333333341e+01, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-28 09:15:02' WHERE "id"=5630;
