UPDATE "recommendations" SET "tmdb_id"=5994, "imdb_id"='tt0218967', "igdb_id"=NULL, "title"='The Family Man', "original_title"='The Family Man', "media_type"='movie', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/9wToOVsKuf0XeKhlauzCa3D8Gui.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gnosJeDIDQXy9uDewXphEpDWNYT.jpg', "overview"='Jack''s lavish, fast-paced lifestyle changes one Christmas night when he stumbles into a grocery store holdup and disarms the gunman. The next morning he wakes up in bed lying next to Kate, his college sweetheart he left in order to pursue his career, and to the horrifying discovery that his former life no longer exists. As he stumbles through this alternate suburban universe, Jack finds himself at a crossroad where he must choose between his high-power career and the woman he loves.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.325, "vote_average"=6.828, "is_ambiguous"=0, "evidence_score"=1.01255555555555556e+01, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-28 09:15:02' WHERE "id"=5643;
UPDATE "recommendations" SET "tmdb_id"=9894, "imdb_id"='tt0115798', "igdb_id"=NULL, "title"='The Cable Guy', "original_title"='The Cable Guy', "media_type"='movie', "release_year"=1996, "poster_url"='https://image.tmdb.org/t/p/w500/YJt9l3RdrRohI95btQKPXwpdii.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nj0rIFyjZ0GUOQYnGM8YyGR3CmS.jpg', "overview"='When recently single Steven moves into his new apartment, cable guy Chip comes to hook him up—and doesn''t let go. Initially, Chip is just overzealous in his desire to be Steven''s pal, but when Steven tries to end the ''friendship'', Chip shows his dark side. He begins stalking Steven, who''s left to fend for himself because no one else can believe Chip''s capable of such behaviour.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.0888, "vote_average"=6.0, "is_ambiguous"=0, "evidence_score"=6.3, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-28 09:15:02' WHERE "id"=5660;
