UPDATE "recommendations" SET "tmdb_id"=11470, "imdb_id"='tt0211443', "igdb_id"=NULL, "title"='Jason X', "original_title"='Jason X', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/ggOND0hfoE0f3K857joSzEeIchb.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fR5Hkf4OH6aLExl2qP2ucMV2Xdt.jpg', "overview"='In the year 2455, Old Earth is now a contaminated planet abandoned for centuries -- a brown world of violent storms, toxic landmasses and poisonous seas. Yet humans have returned to the deadly place that they once fled, not to live, but to research the ancient, rusting artifacts of the long-gone civilizations. But it''s not the harmful environment that could prove fatal to the intrepid, young explorers who have just landed on Old Earth. For them, it''s Friday the 13th, and Jason lives!', "external_url"=NULL, "platforms"=NULL, "popularity"=5.5587, "vote_average"=4.854, "is_ambiguous"=0, "evidence_score"=9.055, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-28 09:15:02' WHERE "id"=6043;
