UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=4754, "title"='Alien: Isolation', "original_title"='Alien: Isolation', "media_type"='game', "release_year"=2014, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co1vzu.jpg', "backdrop_url"=NULL, "overview"='Alien: Isolation is a survival horror game based on the Alien franchise. As Amanda Ripley, daughter of Ellen Ripley, you will navigate through an increasingly volatile world as you find yourself confronted on all sides by a panicked population and an unpredictable Alien. You must scavenge resources, improvise solutions and use your wits, not just to succeed in your mission but to simply stay alive. In addition to the main story mode there''s Survivor mode in which the player needs to escape from a specially designed map fulfilling secondary objectives along the way, while being aggressively hunted by the alien. This mode includes online leaderboards.', "external_url"='https://www.igdb.com/games/alien-isolation', "platforms"='["PlayStation 3", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360", "Xbox One", "Nintendo Switch"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=8.51666666666666571e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-28 09:15:02' WHERE "id"=6100;
