UPDATE "recommendations" SET "tmdb_id"=9275, "imdb_id"='tt0266452', "igdb_id"=NULL, "title"='Death to Smoochy', "original_title"='Death to Smoochy', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/wrwwuNLITsA5N5cVnA3ftvHFqHj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xse1f9OR0PVByGnTChplzUgYz7t.jpg', "overview"='Tells the story of Rainbow Randolph, the corrupt, costumed star of a popular children''s TV show, who is fired over a bribery scandal and replaced by squeaky-clean Smoochy, a puffy fuchsia rhinoceros. As Smoochy catapults to fame - scoring hit ratings and the affections of a network executive - Randolph makes the unsuspecting rhino the target of his numerous outrageous attempts to exact revenge and reclaim his status as America''s sweetheart.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.2142, "vote_average"=5.9, "is_ambiguous"=0, "evidence_score"=7.35333333333333261e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-28 09:15:02' WHERE "id"=6297;
UPDATE "recommendations" SET "tmdb_id"=9481, "imdb_id"='tt0145681', "igdb_id"=NULL, "title"='The Bone Collector', "original_title"='The Bone Collector', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/7atMCqRaDpAOnGsteTRm17zmvN3.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/oOoy2MqPeuDqeedQyouFfitncei.jpg', "overview"='Lincoln Rhyme was the department''s top homicide detective and leading expert in criminal forensics until an injury left him paralyzed, depressed, and incapable of working. But when a gruesome murder in Manhattan leaves detectives baffled, they call on Rhyme to help solve the mystery. Amelia Donaghy, a rookie cop whose quick thinking preserved a gruesome murder scene, is enlisted by Rhyme to be his on-the-scene forensics expert. With Amelia reluctantly acting as Rhyme''s able-bodied go-between, the pair piece together cryptic clues the killer leaves behind at the scene of the crime, hoping to catch the grisly serial killer.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.3087, "vote_average"=6.794, "is_ambiguous"=0, "evidence_score"=5.014, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-28 09:15:02' WHERE "id"=6364;
