UPDATE "recommendations" SET "tmdb_id"=45782, "imdb_id"='tt2250192', "igdb_id"=NULL, "title"='Sword Art Online', "original_title"='ソードアート・オンライン', "media_type"='tv', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/9m8bFIXPg26taNrFSXGwEORVACD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/z7QKvQbOrIhp9uOT63l9dIgHJrb.jpg', "overview"='In the near future, a Virtual Reality Massive Multiplayer Online Role-Playing Game (VRMMORPG) called Sword Art Online has been released where players control their avatars with their bodies using a piece of technology called Nerve Gear. One day, players discover they cannot log out, as the game creator is holding them captive unless they reach the 100th floor of the game''s tower and defeat the final boss. However, if they die in the game, they die in real life. Their struggle for survival starts now...', "external_url"=NULL, "platforms"=NULL, "popularity"=27.2122, "vote_average"=8.154, "is_ambiguous"=0, "evidence_score"=6.26, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-28 09:15:02' WHERE "id"=6438;
