UPDATE "recommendations" SET "tmdb_id"=11532, "imdb_id"='tt0089087', "igdb_id"=NULL, "title"='The Emerald Forest', "original_title"='The Emerald Forest', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/fdRlqPnPFaPyQqS3KiBLJwWQPBe.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8JH97RT7J2zMRDx3ia7wwywkIwV.jpg', "overview"='For ten years, engineer Bill Markham has searched tirelessly for his son Tommy who disappeared from the edge of the Brazilian rainforest. Miraculously, he finds the boy living among the reclusive Amazon tribe who adopted him. And that''s when Bill''s adventure truly begins. For his son is now a grown tribesman who moves skillfully through this beautiful-but-dangerous terrain, fearful only of those who would exploit it. And as Bill attempts to "rescue" him from the savagery of the untamed jungle, Tommy challenges Bill''s idea of true civilization and his notions about who needs rescuing.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.2781, "vote_average"=6.6, "is_ambiguous"=0, "evidence_score"=8.52333333333333342e+00, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-28 09:15:02' WHERE "id"=8750;
