UPDATE "recommendations" SET "tmdb_id"=1287274, "imdb_id"=NULL, "igdb_id"=NULL, "title"='Until the End of the World', "original_title"='Until the End of the World', "media_type"='movie', "release_year"=2024, "poster_url"=NULL, "backdrop_url"=NULL, "overview"='This is an artificial intelligence (AI)-generated film that envisions the Middlesbrough Collection as a sleeping repository of the past and present. Perks and Stewart used the Collection and displays as source material, asking three groups to imagine the dreams of the Collection through creative writing, meditation, observation exercises and karaoke. The resulting material was inputted into ChatGPT to generate a script and then fed into an AI moving image platform, Pictory AI, which translated it into a sequence of moving images from existing databases.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.6412, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=6.01, "created_at"='2026-08-11 02:46:38', "updated_at"='2026-08-28 09:15:02' WHERE "id"=9270;
