UPDATE "recommendations" SET "tmdb_id"=627659, "imdb_id"='tt6470644', "igdb_id"=NULL, "title"='Paper House', "original_title"='纸屋', "media_type"='movie', "release_year"=2017, "poster_url"='https://image.tmdb.org/t/p/w500/jJS0rZDcHMrmSlDouax6zpGOEkT.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/sA3F8KvhHgN0BTJ9iMLlT7a0k9s.jpg', "overview"='Paper House is a short film set against the backdrop of a traditional Chinese funeral and its customs. The film follows the story of a family as they descend into disharmony after the death of their patriarch. The title of the film refers to the old Chinese tradition of burning paper offerings for their deceased loved ones. This short film is a eulogy for this colourful art form that is fast disappearing in Singapore’s modern society.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.0746, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=8.35333333333333349e+00, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-28 09:15:02' WHERE "id"=9382;
